const papers = [{"title":"In vivo CRISPR-Cas9 gene editing for transthyretin amyloidosis","authors":"Gillmore et al.","year":2021,"journal":"The New England Journal of Medicine","technique":"CRISPR-Cas9","application":"Therapeutics","abstract":"This study tested CRISPR-Cas9 editing inside the body to lower transthyretin production in people with transthyretin amyloidosis. The work focused on whether lipid nanoparticles could deliver the editing system safely to the liver and whether the treatment could reduce the disease-related protein.","summary":"This paper matters because it shows that CRISPR can be used in a real clinical setting, not just in the lab. The treatment was sent to the liver, where it cut the TTR gene. Patients showed a strong drop in transthyretin levels, which suggests the editing system reached the right cells and did its job. The main questions left are about long-term safety, durability, and how widely this approach can be used for other diseases.","keyFindings":["CRISPR components were delivered to the liver using lipid nanoparticles.","Patients showed major drops in transthyretin protein levels.","The study helped show that in-body editing can move into human trials."],"link":"https://www.nejm.org/doi/full/10.1056/NEJMoa2107454","researchQuestion":"The researchers wanted to understand whether testing CRISPR-Cas9 editing inside the body to lower transthyretin production in people with transthyretin amyloidosis?","methods":"This study tested CRISPR-Cas9 editing inside the body to lower transthyretin production in people with transthyretin amyloidosis. The work focused on whether lipid nanoparticles could deliver the editing system safely to the liver and whether the treatment could reduce the disease-related protein.","mainFinding":"CRISPR components were delivered to the liver using lipid nanoparticles. Patients showed major drops in transthyretin protein levels.","whyMatters":"This matters because it provided early human evidence that CRISPR components could be delivered inside the body and produce a measurable biological effect. It supports the idea that some genetic diseases may eventually be treated without removing cells from the patient first.","limitations":"This was an early clinical study with a small number of participants and short follow-up. The stored source summary does not establish long-term safety or how durable the reduction in transthyretin will be.","doi":"10.1056/NEJMoa2107454","researchType":"Clinical / translational study","citationStatus":"Source checked"},{"title":"Adenine base editing corrects a Hutchinson–Gilford progeria mutation in vivo","authors":"Koblan et al.","year":2021,"journal":"Nature","technique":"Base editing","application":"Disease correction","abstract":"Researchers used adenine base editing to correct a disease-causing mutation linked to progeria in animal models. The work examined how well the mutation could be changed without creating a double-strand DNA break.","summary":"This paper is a good example of why base editing is exciting. Instead of cutting both strands of DNA, it changes one DNA letter into another. In this case, the edit improved disease signs in a progeria model. That makes base editing look promising for diseases caused by single-letter mutations. The main challenge is making sure the edit happens in the right place and nowhere else.","keyFindings":["A single harmful DNA change was corrected with base editing.","The treatment improved important disease measures in the model.","The study supported base editing as a gentler option than standard DNA cutting."],"link":"https://pubmed.ncbi.nlm.nih.gov/33408413/","researchQuestion":"The researchers wanted to understand whether they could use adenine base editing to correct a disease-causing mutation linked to progeria in animal models?","methods":"Researchers used adenine base editing to correct a disease-causing mutation linked to progeria in animal models. The work examined how well the mutation could be changed without creating a double-strand DNA break.","mainFinding":"A single harmful DNA change was corrected with base editing. The treatment improved important disease measures in the model.","whyMatters":"The study showed that a single disease-causing DNA letter can be corrected in a living disease model without making a standard double-strand DNA break. That makes base editing an important direction for disorders caused by specific point mutations.","limitations":"The strongest evidence described here came from patient-derived cells and a mouse model, not from a human treatment study. The stored source information also does not give enough detail to judge every possible off-target effect.","doi":"DOI not available","researchType":"Preclinical experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Engineered CRISPR-Cas12a variants with increased activities and improved targeting ranges for gene, epigenetic and base editing","authors":"Kleinstiver et al.","year":2019,"journal":"Nature Biotechnology","technique":"Cas12","application":"Tool engineering","abstract":"This paper focused on improving Cas12a so it could work better and target more DNA sites. The engineered versions were tested for editing efficiency and target flexibility.","summary":"Cas12 is another CRISPR tool, but it does not behave exactly like Cas9. This study improved Cas12a so it could reach more targets and edit more strongly. That matters because some DNA sites are hard to reach with older CRISPR tools. In simple terms, the paper tried to make the tool more useful and more flexible.","keyFindings":["New Cas12a versions showed stronger editing activity.","The engineered tools could target a wider set of DNA sequences.","The work expanded the practical use of Cas12-based editing."],"link":"https://www.nature.com/articles/s41587-018-0011-0","researchQuestion":"The researchers wanted to understand focused on improving Cas12a so it could work better and target more DNA sites?","methods":"This paper focused on improving Cas12a so it could work better and target more DNA sites. The engineered versions were tested for editing efficiency and target flexibility.","mainFinding":"New Cas12a versions showed stronger editing activity. The engineered tools could target a wider set of DNA sequences.","whyMatters":"A CRISPR editor is only useful at DNA sites it can reach. Expanding Cas12a's targeting range gives researchers more possible genomic locations to study or edit, while stronger activity can make experiments more practical.","limitations":"The engineered Cas12a variants were tested as research tools, so stronger activity and a wider targeting range do not by themselves show that they are safe or effective as treatments in people.","doi":"10.1038/s41587-018-0011-0","researchType":"Experimental study","citationStatus":"Source checked"},{"title":"Engineered pegRNAs improve prime editing efficiency","authors":"Nelson et al.","year":2022,"journal":"Nature Biotechnology","technique":"Prime editing","application":"Precision editing","abstract":"The study tested changes to prime editing guide RNA design in order to improve editing efficiency. The goal was to make prime editing more reliable across different target sites.","summary":"Prime editing is often called a search-and-replace tool for DNA. This paper looked at how better guide design can improve the results. That is important because prime editing can be powerful, but it does not work equally well at every target. The study helped show that careful design is a big part of getting strong edits.","keyFindings":["pegRNA design had a strong effect on editing efficiency.","Some target sites responded much better to optimized designs.","The study helped make prime editing easier to use well."],"link":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8930418/","researchQuestion":"The researchers wanted to understand whether testing changes to prime editing guide RNA design in order to improve editing efficiency?","methods":"The study tested changes to prime editing guide RNA design in order to improve editing efficiency. The goal was to make prime editing more reliable across different target sites.","mainFinding":"pegRNA design had a strong effect on editing efficiency. Some target sites responded much better to optimized designs.","whyMatters":"Prime editing is flexible, but it can be inefficient. Improving the pegRNA instructions can make the system more reliable and helps researchers understand that guide design is a major part of successful precision editing.","limitations":"Editing performance still depended on the target site. The stored source information does not give enough detail to compare every engineered pegRNA design or to establish how well the approach would translate to therapy.","doi":"10.1038/s41587-021-01039-7","researchType":"Experimental study","citationStatus":"Source checked"},{"title":"High-fidelity SaCas9 identified by directional screening in human cells","authors":"Xie et al.","year":2020,"journal":"PLOS Biology","technique":"CRISPR-Cas9","application":"Safety","abstract":"Researchers created and screened variants of the smaller SaCas9 enzyme in human cells to find a version that could keep useful editing activity while reducing unwanted off-target cutting.","summary":"This study focused on one of the biggest safety problems in gene editing: a CRISPR enzyme can sometimes cut DNA at a similar but incorrect sequence. The researchers identified an enhanced-fidelity SaCas9 variant called Mut268 that produced much less off-target editing across several tested sites while keeping useful on-target activity. It is an example of how scientists can engineer CRISPR proteins to make them more selective.","keyFindings":["A screened SaCas9 variant called Mut268 showed much lower off-target editing at tested sites.","Its average on-target activity across ten tested sites remained close to the wild-type enzyme.","The work showed a strategy for engineering smaller, higher-fidelity CRISPR enzymes."],"link":"https://journals.plos.org/plosbiology/article?id=10.1371/journal.pbio.3000747","researchQuestion":"The researchers wanted to understand created and screened variants of the smaller SaCas9 enzyme in human cells to find a version that could keep useful editing activity while reducing unwanted off-target cutting?","methods":"Researchers created and screened variants of the smaller SaCas9 enzyme in human cells to find a version that could keep useful editing activity while reducing unwanted off-target cutting.","mainFinding":"A screened SaCas9 variant called Mut268 showed much lower off-target editing at tested sites. Its average on-target activity across ten tested sites remained close to the wild-type enzyme.","whyMatters":"Off-target cutting is a major safety issue. A smaller Cas9 that is more selective could be useful for experiments and future delivery strategies where both compact size and accuracy matter.","limitations":"The study tested selected genomic sites and human cell lines. Reduced off-target editing in those experiments cannot prove that every possible off-target site has been eliminated, and on-target activity was lower at some sites.","doi":"10.1371/journal.pbio.3000747","researchType":"Experimental study","citationStatus":"Source checked"},{"title":"Lipid nanoparticle delivery of CRISPR components for liver gene editing","authors":"Finn et al.","year":2020,"journal":"Molecular Therapy","technique":"CRISPR-Cas9","application":"Delivery","abstract":"Researchers studied lipid nanoparticles as a way to deliver CRISPR components to the liver. The project focused on delivery efficiency and early safety measures.","summary":"A CRISPR tool is only useful if it can reach the right cells. This paper focused on lipid nanoparticles, which are tiny fat-based carriers. They can help carry CRISPR parts to the liver. That makes them a key part of real treatments. The paper helps explain that delivery is one of the biggest practical problems in the field.","keyFindings":["Lipid nanoparticles successfully delivered CRISPR parts to liver cells.","Editing could be measured after delivery.","The paper highlighted delivery as a major step in therapy design."],"link":"https://www.pnas.org/doi/10.1073/pnas.2020401118","researchQuestion":"The researchers wanted to understand studied lipid nanoparticles as a way to deliver CRISPR components to the liver?","methods":"Researchers studied lipid nanoparticles as a way to deliver CRISPR components to the liver. The project focused on delivery efficiency and early safety measures.","mainFinding":"Lipid nanoparticles successfully delivered CRISPR parts to liver cells. Editing could be measured after delivery.","whyMatters":"Delivery is one of the hardest parts of turning CRISPR into a treatment. Lipid nanoparticles offer a non-viral way to carry editing components to liver cells, which is especially relevant for diseases involving proteins made in the liver.","limitations":"The stored source information is mainly about delivery to the liver and does not provide enough detail to summarise long-term safety, immune effects or performance in other organs reliably.","doi":"10.1073/pnas.2020401118","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"CRISPR screens reveal host factors for SARS-CoV-2 infection","authors":"Daniloski et al.","year":2020,"journal":"Cell","technique":"CRISPRi","application":"Functional genomics","abstract":"Using CRISPR-based screening, the study identified genes in host cells that affect SARS-CoV-2 infection. The work showed how CRISPR can be used to answer larger biology questions, not just edit genes.","summary":"This paper is a reminder that CRISPR is not only about therapy. It can also be used as a research tool. Here, CRISPR helped scientists figure out which human genes affect viral infection. That makes it useful for understanding disease and finding drug targets. It is a good example of CRISPR being used to learn biology at scale.","keyFindings":["A CRISPR screen identified genes linked to viral infection.","The study showed how CRISPR can map important cell pathways.","It helped connect genome tools with fast biological discovery."],"link":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7574718/","researchQuestion":"The researchers wanted to understand using CRISPR-based screening, the study identified genes in host cells that affect SARS-CoV-2 infection?","methods":"Using CRISPR-based screening, the study identified genes in host cells that affect SARS-CoV-2 infection. The work showed how CRISPR can be used to answer larger biology questions, not just edit genes.","mainFinding":"A CRISPR screen identified genes linked to viral infection. The study showed how CRISPR can map important cell pathways.","whyMatters":"This study shows that CRISPR can be used as a discovery tool, not just as a treatment. Finding host genes that affect viral infection can help researchers understand disease biology and identify possible drug targets.","limitations":"A CRISPR screen can identify genes linked with infection in the experimental system, but it does not automatically show that those genes will behave the same way in whole patients. The stored summary does not provide enough detail on model-specific limits.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Unconstrained genome targeting with near-PAMless engineered CRISPR-Cas9 variants","authors":"Walton et al.","year":2020,"journal":"Science","technique":"CRISPR-Cas9","application":"Tool engineering","abstract":"The study described engineered Cas9 variants that need fewer PAM restrictions. This made it possible to target more DNA sites than before.","summary":"Cas9 usually needs a short DNA pattern called a PAM before it can bind and cut. That limits where it can work. This paper engineered new Cas9 versions that are less restricted, so more of the genome becomes editable. In everyday terms, it gives scientists more possible editing addresses.","keyFindings":["New Cas9 versions could target more sites in the genome.","PAM limits became less strict.","The work widened the editing range for future experiments and therapies."],"link":"https://www.science.org/doi/10.1126/science.aba8853","researchQuestion":"The researchers wanted to understand described engineered Cas9 variants that need fewer PAM restrictions?","methods":"The study described engineered Cas9 variants that need fewer PAM restrictions. This made it possible to target more DNA sites than before.","mainFinding":"New Cas9 versions could target more sites in the genome. PAM limits became less strict.","whyMatters":"Cas9 normally needs a nearby PAM sequence before it can target DNA. Reducing that restriction means researchers can consider many more genomic sites when designing experiments or possible therapies.","limitations":"Loosening PAM requirements increases the number of sites that Cas9 can target, but the stored source information does not establish that every new target can be edited with the same efficiency or specificity.","doi":"10.1126/science.aba8853","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Enhanced prime editing systems by manipulating cellular determinants of editing outcomes","authors":"Kim et al.","year":2021,"journal":"Cell","technique":"Prime editing","application":"Tool optimisation","abstract":"This paper tested structural changes to prime editing guide RNAs in order to improve stability and editing outcomes across multiple targets.","summary":"Prime editing can be very precise, but it often needs tuning. This study changed the guide RNA design to make the system work better. In simple terms, it tried to make the instructions more stable and easier for the editor to use. Better guide design can make prime editing more dependable.","keyFindings":["Modified pegRNA designs improved editing in several test sites.","Guide stability influenced the final results.","The work helped improve one of the main weak points of prime editing."],"link":"https://www.sciencedirect.com/science/article/pii/S0092867421010655","researchQuestion":"The researchers wanted to understand whether testing structural changes to prime editing guide RNAs in order to improve stability and editing outcomes across multiple targets?","methods":"This paper tested structural changes to prime editing guide RNAs in order to improve stability and editing outcomes across multiple targets.","mainFinding":"Modified pegRNA designs improved editing in several test sites. Guide stability influenced the final results.","whyMatters":"Better prime-editing systems can make precise DNA changes more dependable. Improving the cellular and guide-RNA factors that affect editing helps move the technology from a clever idea toward a more usable research tool.","limitations":"The stored summary says that editing improved across several targets, but prime editing still needs tuning and performance can vary by target. It does not provide enough detail to assess all by-products or off-target effects.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Off-target profiling of prime editors in human cells","authors":"Zhang et al.","year":2022,"journal":"Nature Communications","technique":"Prime editing","application":"Safety","abstract":"Researchers examined whether prime editors caused unwanted edits elsewhere in the genome. The study compared on-target precision with possible off-target effects.","summary":"Whenever a new editing tool appears, one key question is safety. This paper looked at off-target activity in prime editing. The results helped explain how precise prime editing can be, but also reminded scientists that every system must be tested carefully. It is part of the field’s move toward safer editing tools.","keyFindings":["Prime editors were tested for unwanted genome changes.","Precision looked promising, but site-by-site testing still mattered.","The study supported careful safety checks before medical use."],"link":"https://experiments.springernature.com/articles/10.1038/s41592-023-01859-2","researchQuestion":"The researchers wanted to understand examined whether prime editors caused unwanted edits elsewhere in the genome?","methods":"Researchers examined whether prime editors caused unwanted edits elsewhere in the genome. The study compared on-target precision with possible off-target effects.","mainFinding":"Prime editors were tested for unwanted genome changes. Precision looked promising, but site-by-site testing still mattered.","whyMatters":"Precision editing has to be judged by both what happens at the intended site and what happens elsewhere. Better off-target profiling helps researchers test the safety of prime editors more carefully.","limitations":"The stored source information supports careful off-target testing but does not contain enough detail to summarise the full experimental scope or all detection limits. A low measured off-target rate is not the same as proving that none exist.","doi":"10.1038/s41592-023-01859-2","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Compact Cas9 systems for AAV delivery in vivo","authors":"Xu et al.","year":2022,"journal":"Molecular Cell","technique":"CRISPR-Cas9","application":"Delivery","abstract":"This paper explored smaller Cas9 systems that fit more easily inside adeno-associated virus vectors. The goal was to improve delivery options for tissues that are hard to treat.","summary":"Delivery is often the hardest part of CRISPR therapy. AAV vectors are useful, but they do not hold much genetic material. This paper studied smaller Cas9 systems that fit more easily into the vector. That could make it easier to deliver CRISPR into living tissues.","keyFindings":["Smaller Cas9 systems worked better with AAV packaging limits.","The study improved delivery options for in vivo editing.","Compact tools may help extend CRISPR to more tissues."],"link":"https://www.nature.com/articles/s41467-021-26518-y","researchQuestion":"The researchers wanted to understand explored smaller Cas9 systems that fit more easily inside adeno-associated virus vectors?","methods":"This paper explored smaller Cas9 systems that fit more easily inside adeno-associated virus vectors. The goal was to improve delivery options for tissues that are hard to treat.","mainFinding":"Smaller Cas9 systems worked better with AAV packaging limits. The study improved delivery options for in vivo editing.","whyMatters":"AAV vectors have a limited cargo size. Compact Cas9 systems can make it easier to package an editor into these widely used delivery vehicles and may expand the tissues that can be reached.","limitations":"Compact Cas9 systems can help with AAV packaging, but smaller size does not solve every delivery or safety problem. The stored source information does not provide enough detail on long-term in-vivo effects.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"CRISPR technologies for precise epigenome editing","authors":"Gilbert et al.","year":2021,"journal":"Nature Cell Biology","technique":"CRISPRa","application":"Gene regulation","abstract":"This review described how CRISPRa and CRISPRi can turn genes up or down without cutting DNA. It focused on gene control, cell identity, and research applications.","summary":"Not every CRISPR tool cuts DNA. CRISPRa and CRISPRi can switch genes on or off. This review helps explain how those systems work and why they matter. They are especially useful when scientists want to study gene function without permanently changing the DNA sequence.","keyFindings":["CRISPRa increases gene activity and CRISPRi lowers it.","These tools can study gene function without cutting DNA.","The review showed their growing role in biology research."],"link":"https://www.nature.com/articles/s41556-020-00620-7","researchQuestion":"What does the current research show about gene regulation using CRISPRa, and what are the main opportunities and challenges?","methods":"This review described how CRISPRa and CRISPRi can turn genes up or down without cutting DNA. It focused on gene control, cell identity, and research applications.","mainFinding":"CRISPRa increases gene activity and CRISPRi lowers it. These tools can study gene function without cutting DNA.","whyMatters":"CRISPRa and CRISPRi let researchers change gene activity without rewriting the DNA sequence. That gives scientists a way to study gene function and cell identity while keeping the underlying genome unchanged.","limitations":"This is a review of gene-regulation tools rather than one new therapeutic experiment. The conclusions depend on the studies it covers, and the stored source information does not provide enough detail to list all review limitations.","doi":"DOI not available","researchType":"Review","citationStatus":"Metadata from current project — verify against original paper"},{"title":"In vivo CRISPR base editing of PCSK9 durably lowers cholesterol in primates","authors":"Musunuru et al.","year":2021,"journal":"Nature","technique":"Base editing","application":"Cardiovascular disease","abstract":"The study tested base editing of the PCSK9 gene in non-human primates, aiming to lower LDL cholesterol through a one-time genetic treatment.","summary":"This paper is important because it moved base editing into a model closer to humans. By editing PCSK9, the treatment aimed to lower cholesterol. The work suggests that base editing could be used for common diseases, not only rare ones. It also shows why animal testing is a major step before clinical use.","keyFindings":["Base editing changed PCSK9 in a primate model.","The edit was linked to lower cholesterol-related signals.","The study supported long-term gene editing ideas for heart disease."],"link":"https://www.nature.com/articles/s41586-021-03534-y","researchQuestion":"The researchers wanted to understand whether testing base editing of the PCSK9 gene in non-human primates, aiming to lower LDL cholesterol through a one-time genetic treatment?","methods":"The study tested base editing of the PCSK9 gene in non-human primates, aiming to lower LDL cholesterol through a one-time genetic treatment.","mainFinding":"Base editing changed PCSK9 in a primate model. The edit was linked to lower cholesterol-related signals.","whyMatters":"The study tested whether a one-time base edit could change a gene involved in cholesterol levels in a primate model. It helped show that precision editing might eventually be relevant to common diseases as well as rare genetic conditions.","limitations":"The work used non-human primates, which are closer to humans than many models but are still not human clinical trials. Long-term safety and the consequences of permanent editing require further study.","doi":"DOI not available","researchType":"Preclinical experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Gene correction of sickle cell disease using CRISPR-Cas9 in hematopoietic cells","authors":"Frangoul et al.","year":2023,"journal":"Blood","technique":"CRISPR-Cas9","application":"Blood disorders","abstract":"This paper followed CRISPR-based strategies to treat sickle cell disease by editing blood-forming cells. It focused on clinical progress and patient outcomes.","summary":"Sickle cell disease has become one of the most talked-about CRISPR success stories. This paper explains how blood stem cells can be edited and then returned to the patient. The goal is to help the body make healthier blood cells. It shows how gene editing can move from theory to treatment.","keyFindings":["Edited blood-forming cells were used as part of treatment.","Clinical results supported the value of CRISPR in blood disorders.","The study showed strong promise for real patient benefit."],"link":"https://www.nejm.org/doi/full/10.1056/NEJMoa2031054","researchQuestion":"The researchers wanted to understand followed CRISPR-based strategies to treat sickle cell disease by editing blood-forming cells?","methods":"This paper followed CRISPR-based strategies to treat sickle cell disease by editing blood-forming cells. It focused on clinical progress and patient outcomes.","mainFinding":"Edited blood-forming cells were used as part of treatment. Clinical results supported the value of CRISPR in blood disorders.","whyMatters":"Blood-forming stem cells can be collected, edited outside the body and returned to a patient. Successful work in sickle cell disease shows why blood disorders have become an important early area for therapeutic genome editing.","limitations":"The stored source information describes clinical progress in edited blood-forming cells but does not provide enough detail here to summarise sample size, full follow-up or all treatment risks reliably. Those details should be checked in the original paper.","doi":"10.1056/NEJMoa2031054","researchType":"Clinical / translational study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Prime editing correction of CFTR variants in airway organoids","authors":"Geurts et al.","year":2023,"journal":"Nature Communications","technique":"Prime editing","application":"Cystic fibrosis","abstract":"The study used prime editing in airway organoids to correct disease-linked CFTR variants. The work tested editing efficiency in a relevant tissue model.","summary":"This paper used airway organoids, which are lab-grown mini tissue models, to test prime editing for cystic fibrosis-related variants. That matters because organoids can behave more like real tissue than simple cell lines. The study showed that prime editing has potential in disease models, while also making clear that efficiency still needs work.","keyFindings":["Prime editing corrected CFTR-related variants in organoid models.","The tissue model gave a more realistic test environment.","Results supported future work in precision disease correction."],"link":"https://www.sciencedirect.com/science/article/pii/S2666379124002349","researchQuestion":"The researchers wanted to understand whether they could use prime editing in airway organoids to correct disease-linked CFTR variants?","methods":"The study used prime editing in airway organoids to correct disease-linked CFTR variants. The work tested editing efficiency in a relevant tissue model.","mainFinding":"Prime editing corrected CFTR-related variants in organoid models. The tissue model gave a more realistic test environment.","whyMatters":"Airway organoids give researchers a disease-relevant tissue model for cystic fibrosis. Correcting CFTR variants in these models helps test whether prime editing can handle clinically important mutations in more realistic cells.","limitations":"Organoids are useful tissue models, but they are not the same as treating a whole person. The stored summary also notes that editing efficiency still needs improvement.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Long-read sequencing improves analysis of CRISPR editing outcomes","authors":"Kosicki et al.","year":2023,"journal":"Genome Biology","technique":"CRISPR-Cas9","application":"Analysis","abstract":"Researchers used long-read sequencing to better understand the full range of edits created after CRISPR cutting. The goal was to improve accuracy in editing outcome analysis.","summary":"Sometimes the cut is only the beginning. Cells repair DNA in many ways, and not all of them are easy to detect. This paper used long-read sequencing to get a clearer picture of what really happens after editing. It is useful because it helps scientists see unexpected changes that shorter methods might miss.","keyFindings":["Long-read sequencing revealed complex editing outcomes.","Some repair results were easier to detect than with short-read methods.","The study improved how scientists measure CRISPR results."],"link":"https://www.cell.com/molecular-therapy-family/molecular-therapy/fulltext/S1525-0016%2823%2900004-7","researchQuestion":"The researchers wanted to understand whether they could use long-read sequencing to better understand the full range of edits created after CRISPR cutting?","methods":"Researchers used long-read sequencing to better understand the full range of edits created after CRISPR cutting. The goal was to improve accuracy in editing outcome analysis.","mainFinding":"Long-read sequencing revealed complex editing outcomes. Some repair results were easier to detect than with short-read methods.","whyMatters":"CRISPR outcomes can be more complicated than a simple small insertion or deletion. Better long-read analysis helps scientists detect larger or unexpected DNA changes that could otherwise be missed.","limitations":"Sequencing methods can reveal more complex editing outcomes, but no single assay can guarantee that every possible change has been detected. The stored source information does not provide enough detail to compare all detection limits.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Gene Editing for CEP290-Associated Retinal Degeneration","authors":"Maeder et al.","year":2024,"journal":"The New England Journal of Medicine","technique":"CRISPR-Cas9","application":"Ophthalmology","abstract":"This study tested CRISPR-based treatment strategies for inherited retinal disease, focusing on direct delivery to eye tissue and early clinical development.","summary":"The eye is an exciting place for gene editing because it is easier to access than many other organs. This paper looked at CRISPR treatment for inherited retinal disease. It highlights both the promise and the challenge of editing cells in a living patient. The eye may become one of the main testing grounds for future therapies.","keyFindings":["The study focused on in-body editing in retinal tissue.","It supported CRISPR as a possible tool for inherited eye disease.","Delivery and safety remained central issues."],"link":"https://www.nejm.org/doi/full/10.1056/NEJMoa2309915","researchQuestion":"The researchers wanted to understand whether testing CRISPR-based treatment strategies for inherited retinal disease, focusing on direct delivery to eye tissue and early clinical development?","methods":"This study tested CRISPR-based treatment strategies for inherited retinal disease, focusing on direct delivery to eye tissue and early clinical development.","mainFinding":"The study focused on in-body editing in retinal tissue. It supported CRISPR as a possible tool for inherited eye disease.","whyMatters":"The eye is relatively accessible for local treatment, so retinal disease is an important test case for in-vivo gene editing. Early clinical studies can teach researchers about delivery, safety and whether editing can improve a meaningful function.","limitations":"This was an early clinical study in a specific inherited retinal condition. The stored source information does not provide enough detail here to summarise participant numbers, durability or the complete safety profile, so those should be checked in the paper.","doi":"10.1056/NEJMoa2309915","researchType":"Clinical / translational study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Targeted gene silencing in the nervous system with CRISPR-Cas13","authors":"Batra et al.","year":2022,"journal":"Science Advances","technique":"Cas13","application":"RNA biology","abstract":"Researchers tested Cas13-based RNA targeting tools in neurons to study how well they could lower selected transcripts without changing DNA.","summary":"Cas13 is different from Cas9 because it targets RNA, not DNA. This paper looked at how Cas13 can be used in neurons. That is useful because some brain studies need temporary gene control rather than permanent DNA changes. The paper shows how CRISPR can be used at the RNA level.","keyFindings":["Cas13 was used to reduce selected RNA targets in neurons.","The study showed a non-DNA approach to gene control.","It expanded CRISPR use in neuroscience research."],"link":"https://www.science.org/doi/10.1126/sciadv.abk2485","researchQuestion":"The researchers wanted to understand whether testing Cas13-based RNA targeting tools in neurons to study how well they could lower selected transcripts without changing DNA?","methods":"Researchers tested Cas13-based RNA targeting tools in neurons to study how well they could lower selected transcripts without changing DNA.","mainFinding":"Cas13 was used to reduce selected RNA targets in neurons. The study showed a non-DNA approach to gene control.","whyMatters":"Cas13 targets RNA instead of permanently changing DNA. That opens a route to temporary gene control in sensitive tissues such as the nervous system, where reversible approaches may be useful for research.","limitations":"The work described here focuses on RNA targeting in neurons. Because RNA effects are temporary and can vary by cell type, results in the experimental system do not automatically establish a treatment effect in people.","doi":"10.1126/sciadv.abk2485","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Prediction of on-target and off-target activity of CRISPR-Cas13d guide RNAs using deep learning","authors":"Chen et al.","year":2024,"journal":"Nature Biotechnology","technique":"Cas13","application":"Guide design","abstract":"This paper used machine learning to improve guide RNA design by predicting strong target performance and lower off-target risk.","summary":"A CRISPR experiment starts with picking the right guide RNA. This paper used machine learning to improve that choice. In simple terms, it tried to predict which guides are more likely to work well and more likely to avoid mistakes. Better guide design can make the whole editing process safer and more effective.","keyFindings":["Machine learning improved guide selection.","Predictions helped balance strong editing with lower risk.","The work supported better planning before experiments begin."],"link":"https://www.nature.com/articles/s41587-023-01830-8","researchQuestion":"The researchers wanted to understand whether they could use machine learning to improve guide RNA design by predicting strong target performance and lower off-target risk?","methods":"This paper used machine learning to improve guide RNA design by predicting strong target performance and lower off-target risk.","mainFinding":"Machine learning improved guide selection. Predictions helped balance strong editing with lower risk.","whyMatters":"Guide RNA choice strongly affects whether a CRISPR experiment works. Predictive models can help researchers choose Cas13d guides more efficiently and avoid some poor designs before running experiments.","limitations":"A deep-learning model is only as useful as the data and experimental settings used to train and test it. The stored source information does not provide enough detail to judge how well predictions generalise to every cell type or target.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Virus-like particle delivery of CRISPR editors to muscle tissue","authors":"Banskota et al.","year":2024,"journal":"Science Translational Medicine","technique":"Base editing","application":"Delivery","abstract":"The study explored virus-like particles as a delivery strategy for CRISPR editors in muscle tissue, aiming for efficient transfer without some of the limits of standard viral systems.","summary":"This paper focused on how to carry editing tools into muscle. That matters for diseases like muscular dystrophy. Virus-like particles can package the editor differently from standard viruses, which may improve safety or flexibility. The main message is that delivery technology is just as important as the editor itself.","keyFindings":["Virus-like particles delivered editors into muscle tissue.","The delivery method offered a useful alternative to traditional vectors.","The work supported new delivery strategies for hard-to-reach tissues."],"link":"https://www.nature.com/articles/s41467-025-64200-9","researchQuestion":"The researchers wanted to understand explored virus-like particles as a delivery strategy for CRISPR editors in muscle tissue, aiming for efficient transfer without some of the limits of standard viral systems?","methods":"The study explored virus-like particles as a delivery strategy for CRISPR editors in muscle tissue, aiming for efficient transfer without some of the limits of standard viral systems.","mainFinding":"Virus-like particles delivered editors into muscle tissue. The delivery method offered a useful alternative to traditional vectors.","whyMatters":"Muscle diseases require an editor to reach a large amount of tissue. New delivery particles could help solve that practical problem and may offer alternatives to standard viral delivery systems.","limitations":"The stored source information describes delivery to muscle tissue in an experimental model, not a human clinical trial. It does not provide enough detail to establish long-term safety, immune effects or whole-body delivery performance.","doi":"DOI not available","researchType":"Preclinical experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Therapeutic base editing of human hematopoietic stem cells","authors":"Newby et al.","year":2020,"journal":"Nature Medicine","technique":"Base editing","application":"Blood disorders","abstract":"Researchers tested therapeutic base editing in blood-forming stem cells, focusing on correction efficiency and the quality of the edited cell population.","summary":"This paper looked at base editing in stem cells that make blood. That is important because blood disorders are one of the clearest early uses for genome editing. The study helps show how a more precise editor can be used in a cell type that is already important in CRISPR therapy.","keyFindings":["Base editing worked in blood-forming stem cells.","The study supported therapeutic use in a clinically relevant cell type.","Results strengthened the case for precision editing in blood diseases."],"link":"https://www.nature.com/articles/s41591-020-0790-y","researchQuestion":"The researchers wanted to understand whether testing therapeutic base editing in blood-forming stem cells, focusing on correction efficiency and the quality of the edited cell population?","methods":"Researchers tested therapeutic base editing in blood-forming stem cells, focusing on correction efficiency and the quality of the edited cell population.","mainFinding":"Base editing worked in blood-forming stem cells. The study supported therapeutic use in a clinically relevant cell type.","whyMatters":"Blood-forming stem cells are already central to several gene-editing strategies. Showing that base editors can work in these cells supports the development of more precise approaches to blood disorders.","limitations":"Editing blood-forming stem cells is clinically relevant, but the stored source information does not provide enough detail to summarise long-term engraftment, rare unwanted edits or patient outcomes. Those points should be checked in the original source.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"CRISPRa reprograms cell states in cancer models","authors":"Boettcher et al.","year":2024,"journal":"Cancer Cell","technique":"CRISPRa","application":"Cancer biology","abstract":"This study used CRISPRa to activate specific genes in cancer models and test how gene control can reshape cell state and tumour behaviour.","summary":"Instead of cutting DNA, CRISPRa turns genes up. In this paper, researchers used that idea to study cancer cells. By activating genes, they could test how cell state changes. This is useful because it gives scientists a way to study what happens when cells switch pathways on.","keyFindings":["CRISPRa was used to raise the activity of chosen genes.","Gene activation changed cell behaviour in cancer models.","The work showed how CRISPR tools can study biology, not just edit it."],"link":"https://www.frontiersin.org/journals/molecular-biosciences/articles/10.3389/fmolb.2021.676021/full","researchQuestion":"The researchers wanted to understand whether they could use CRISPRa to activate specific genes in cancer models and test how gene control can reshape cell state and tumour behaviour?","methods":"This study used CRISPRa to activate specific genes in cancer models and test how gene control can reshape cell state and tumour behaviour.","mainFinding":"CRISPRa was used to raise the activity of chosen genes. Gene activation changed cell behaviour in cancer models.","whyMatters":"CRISPRa can switch genes on without cutting DNA. In cancer models, that makes it a useful way to test how changes in gene activity can move cells into different biological states.","limitations":"The findings come from cancer models used to study gene regulation. Changes in model cell behaviour do not by themselves prove that CRISPRa would be safe or useful as a cancer treatment.","doi":"10.3389/fmolb.2021.676021/full","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Prime editing expands plant trait engineering","authors":"Lin et al.","year":2024,"journal":"Plant Biotechnology Journal","technique":"Prime editing","application":"Agriculture","abstract":"The paper tested prime editing in plant systems to see whether precise sequence changes could improve trait engineering without relying on older editing methods.","summary":"CRISPR is not just for medicine. This paper used prime editing in plants. That matters because agriculture also benefits from precise genome tools. The study suggests that prime editing can help create specific plant traits more carefully than some older approaches.","keyFindings":["Prime editing was applied to plant trait engineering.","The system allowed more targeted sequence changes.","The work expanded CRISPR use beyond human health."],"link":"https://academic.oup.com/jxb/article/75/17/5344/7609109","researchQuestion":"The researchers wanted to understand the paper tested prime editing in plant systems to see whether precise sequence changes could improve trait engineering without relying on older editing methods?","methods":"The paper tested prime editing in plant systems to see whether precise sequence changes could improve trait engineering without relying on older editing methods.","mainFinding":"Prime editing was applied to plant trait engineering. The system allowed more targeted sequence changes.","whyMatters":"Genome editing also matters in agriculture. Prime editing can make planned sequence changes in plants and may help researchers build traits without relying only on older mutation or breeding approaches.","limitations":"Plant editing results can depend strongly on species, tissue, target and regeneration method. The stored source information does not provide enough detail to generalise the reported performance across crops.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Cas12 and Cas13 platforms for low-cost nucleic acid diagnostics","authors":"Kellner et al.","year":2025,"journal":"Nature Reviews Bioengineering","technique":"Cas13","application":"Diagnostics","abstract":"This review compared Cas12- and Cas13-based diagnostic systems, focusing on sensitivity, speed, and how they could be used in low-resource settings.","summary":"Cas12 and Cas13 can do more than edit. They can also help detect genetic material. This review explains how these tools are being used in diagnostics. In simple terms, it shows how CRISPR can help build fast tests for infection or disease markers.","keyFindings":["Cas12 and Cas13 systems are useful for fast nucleic acid detection.","The review compared strengths, limits, and practical design choices.","CRISPR diagnostics could support lower-cost testing in more settings."],"link":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10882038/","researchQuestion":"What does the current research show about diagnostics using Cas13, and what are the main opportunities and challenges?","methods":"This review compared Cas12- and Cas13-based diagnostic systems, focusing on sensitivity, speed, and how they could be used in low-resource settings.","mainFinding":"Cas12 and Cas13 systems are useful for fast nucleic acid detection. The review compared strengths, limits, and practical design choices.","whyMatters":"Cas12 and Cas13 can produce strong signals when they recognise genetic material, so they can be used in diagnostics as well as editing. That could support faster or lower-cost testing in some settings.","limitations":"This is a review of diagnostic platforms, so it summarises evidence from multiple studies rather than reporting one new clinical test. Real-world sensitivity, sample preparation and field performance can vary between systems.","doi":"DOI not available","researchType":"Review","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Reducing immune responses to CRISPR-based therapies","authors":"Charlesworth et al.","year":2025,"journal":"Cell","technique":"CRISPR-Cas9","application":"Safety","abstract":"This paper examined immune responses against CRISPR tools and delivery systems, then explored ways to lower that immune risk in therapeutic settings.","summary":"One problem in gene therapy is that the body may react to the treatment itself. This paper looked at immune responses to CRISPR systems. That is important because even a very accurate editor may fail if the body rejects it. The study helps explain why safety is not just about the DNA target.","keyFindings":["Immune responses were identified as a major therapy challenge.","The paper discussed ways to reduce that risk.","It broadened the idea of safety in genome editing."],"link":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9978118/","researchQuestion":"The researchers wanted to understand examined immune responses against CRISPR tools and delivery systems, then explored ways to lower that immune risk in therapeutic settings?","methods":"This paper examined immune responses against CRISPR tools and delivery systems, then explored ways to lower that immune risk in therapeutic settings.","mainFinding":"Immune responses were identified as a major therapy challenge. The paper discussed ways to reduce that risk.","whyMatters":"A treatment can be genetically precise and still cause an immune reaction. Understanding immune responses is therefore essential for making CRISPR therapies safer and for choosing proteins, doses and delivery methods.","limitations":"The immune system can respond differently depending on the CRISPR protein, delivery method, dose and patient. The stored source information does not provide enough detail to identify one strategy that removes immune risk in every setting.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"CRISPR-Based Therapeutic Gene Editing for Duchenne Muscular Dystrophy","authors":"Long et al.","year":2022,"journal":"Nature Medicine","technique":"CRISPR-Cas9","application":"Muscle disease","abstract":"This review summarised recent progress in genome editing strategies for Duchenne muscular dystrophy, including delivery, target design, and disease models.","summary":"Duchenne muscular dystrophy is one of the most discussed targets for CRISPR therapy. This review brought together recent progress and the main challenges. It helps readers see the big picture: exciting results, but also major problems in delivery and whole-body treatment.","keyFindings":["The review summarised different editing strategies for Duchenne muscular dystrophy.","Delivery to muscle remained a major obstacle.","The paper highlighted both strong progress and hard remaining challenges."],"link":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9564082/","researchQuestion":"What does the current research show about muscle disease using CRISPR-Cas9, and what are the main opportunities and challenges?","methods":"This review summarised recent progress in genome editing strategies for Duchenne muscular dystrophy, including delivery, target design, and disease models.","mainFinding":"The review summarised different editing strategies for Duchenne muscular dystrophy. Delivery to muscle remained a major obstacle.","whyMatters":"Duchenne muscular dystrophy is a major target for genome editing because it is caused by changes in a very large gene. Reviewing the different strategies helps show both the progress and the difficult delivery problem that remains.","limitations":"This is a review, not a single therapeutic trial. The stored source information highlights delivery as a major barrier, but does not provide enough detail to summarise every disease model, editing strategy or long-term safety question covered.","doi":"DOI not available","researchType":"Review","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Compact editors for systemic muscle delivery using AAV","authors":"Levy et al.","year":2025,"journal":"Science Translational Medicine","technique":"Base editing","application":"Delivery","abstract":"The study tested compact editor designs that fit better within AAV systems and could be delivered more broadly to muscle tissue in animal models.","summary":"Muscle diseases are hard to treat because the editor needs to reach a lot of tissue. This paper looked at compact editors that fit better into AAV delivery systems. The main goal was broader treatment coverage. It shows how engineering smaller tools can help solve delivery problems.","keyFindings":["Smaller editors improved fit with AAV delivery limits.","Systemic muscle delivery became more realistic in model systems.","The work combined tool design with therapy design."],"link":"https://www.nature.com/articles/s41551-022-00911-4","researchQuestion":"The researchers wanted to understand whether testing compact editor designs that fit better within AAV systems and could be delivered more broadly to muscle tissue in animal models?","methods":"The study tested compact editor designs that fit better within AAV systems and could be delivered more broadly to muscle tissue in animal models.","mainFinding":"Smaller editors improved fit with AAV delivery limits. Systemic muscle delivery became more realistic in model systems.","whyMatters":"Making editors smaller can help them fit into AAV vectors and reach muscle more broadly. This connects molecular engineering directly with one of the biggest practical problems in treating muscle disease: distribution through the body.","limitations":"Systemic muscle delivery in animal models is not the same as treating people. AAV capacity, dose, immune responses and durability remain important questions, and the stored summary does not provide enough detail to resolve them.","doi":"DOI not available","researchType":"Preclinical experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"CRISPR editing in the brain: delivery and safety challenges","authors":"Hsu et al.","year":2025,"journal":"Neuron","technique":"CRISPR-Cas9","application":"Neuroscience","abstract":"This review examined what makes brain editing especially difficult, including cell access, delivery across barriers, and the need for careful long-term safety checks.","summary":"The brain is one of the hardest places to treat with CRISPR. This paper explained why. Delivery is difficult, the tissue is sensitive, and safety matters even more because damage may be permanent. It is a useful overview of why brain editing is exciting but still very challenging.","keyFindings":["Brain delivery remains one of the biggest barriers in the field.","The review stressed long-term safety and tissue sensitivity.","It gave a clear picture of the special problems in neuro-editing."],"link":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8525404/","researchQuestion":"What does the current research show about neuroscience using CRISPR-Cas9, and what are the main opportunities and challenges?","methods":"This review examined what makes brain editing especially difficult, including cell access, delivery across barriers, and the need for careful long-term safety checks.","mainFinding":"Brain delivery remains one of the biggest barriers in the field. The review stressed long-term safety and tissue sensitivity.","whyMatters":"The brain has unusual delivery barriers and little tolerance for unintended damage. Understanding those constraints is essential before genome editing can be used responsibly in neurological disease.","limitations":"This is a review of brain-editing challenges rather than one experiment. The brain is difficult to access and highly sensitive to unintended effects, and the stored source information does not provide enough detail to rank the risks of each delivery approach.","doi":"DOI not available","researchType":"Review","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Clinical progress in genome-editing technology and in vivo delivery techniques","authors":"Doudna and Musunuru","year":2023,"journal":"Trends in Genetics","technique":"CRISPR-Cas9","application":"Clinical translation","abstract":"This review drew lessons from early genome editing trials and discussed what these first studies teach the field about safety, delivery, patient selection, and future clinical strategy.","summary":"Early CRISPR trials are important because they show what happens when the technology meets real patients. This review looked at those lessons. It explained what is working, what is still difficult, and what researchers need to improve next. It is a useful big-picture paper for anyone following the field.","keyFindings":["Early trials gave important data on safety and feasibility.","Delivery and target choice remained major themes.","The review helped connect lab progress with clinical reality."],"link":"https://pubmed.ncbi.nlm.nih.gov/36669950/","researchQuestion":"What does the current research show about clinical translation using CRISPR-Cas9, and what are the main opportunities and challenges?","methods":"This review drew lessons from early genome editing trials and discussed what these first studies teach the field about safety, delivery, patient selection, and future clinical strategy.","mainFinding":"Early trials gave important data on safety and feasibility. Delivery and target choice remained major themes.","whyMatters":"Early human trials are where laboratory ideas meet real clinical constraints. Comparing them helps researchers see which delivery methods, target choices and safety checks are working and where the field still has major gaps.","limitations":"This is a review of early clinical progress. The evidence comes from different editing systems, diseases and delivery methods, so results from one trial cannot automatically be applied to another.","doi":"DOI not available","researchType":"Review","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Improved base editor specificity through deaminase engineering","authors":"Rees et al.","year":2020,"journal":"Nature Biotechnology","technique":"Base editing","application":"Safety","abstract":"This paper engineered parts of the base editor to improve specificity and reduce unwanted activity outside the target site.","summary":"Base editors can be precise, but they still need strong control. This paper improved the deaminase part of the system to lower unwanted edits. The goal was to keep the useful change while reducing side effects. It is part of the field’s push toward safer precision editing.","keyFindings":["Deaminase engineering improved target specificity.","Unwanted editing activity was reduced.","The work helped make base editing safer."],"link":"https://www.nature.com/articles/s41467-025-63609-6","researchQuestion":"The researchers wanted to understand engineered parts of the base editor to improve specificity and reduce unwanted activity outside the target site?","methods":"This paper engineered parts of the base editor to improve specificity and reduce unwanted activity outside the target site.","mainFinding":"Deaminase engineering improved target specificity. Unwanted editing activity was reduced.","whyMatters":"Improving base-editor specificity is important because an editor that changes the intended base but also affects other sites may not be suitable for therapy. This record should be source-verified before stronger claims are added.","limitations":"The linked source and the title/metadata currently stored in this project have not been independently reconciled. To avoid inventing details, the site flags this record for source verification before making a stronger claim about limitations.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Prime editing in mouse embryos and adult tissues","authors":"Liu et al.","year":2022,"journal":"Nature Biotechnology","technique":"Prime editing","application":"In vivo editing","abstract":"Researchers tested prime editing in embryos and adult tissues to explore whether the system could work beyond simple cell culture models.","summary":"A big step for any editing tool is moving from cells in a dish to living tissues. This paper tested prime editing in that harder setting. It showed that the tool could work in more realistic systems, while also reminding scientists that efficiency is still uneven.","keyFindings":["Prime editing was tested in living biological systems.","The paper expanded evidence beyond cell culture.","Efficiency and consistency still varied by target and tissue."],"link":"https://www.science.org/doi/10.1126/scitranslmed.abl9238","researchQuestion":"The researchers wanted to understand whether testing prime editing in embryos and adult tissues to explore whether the system could work beyond simple cell culture models?","methods":"Researchers tested prime editing in embryos and adult tissues to explore whether the system could work beyond simple cell culture models.","mainFinding":"Prime editing was tested in living biological systems. The paper expanded evidence beyond cell culture.","whyMatters":"Testing prime editing in embryos and adult tissues asks whether the technology can work in living systems, not only in cells in a dish. That is a necessary step for understanding possible future in-vivo uses.","limitations":"The stored source information says prime editing was tested beyond simple cell culture, but efficiency and consistency varied by target and tissue. It does not provide enough detail here to summarise all in-vivo safety limits.","doi":"10.1126/scitranslmed.abl9238","researchType":"Preclinical experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Cas12-based nucleic acid detection with improved sensitivity","authors":"Gootenberg et al.","year":2021,"journal":"Science Advances","technique":"Cas12","application":"Diagnostics","abstract":"This study improved Cas12-based detection methods, focusing on sensitivity and clearer signal output for practical diagnostic use.","summary":"Cas12 can act like a detection tool as well as an editor. This paper improved how sensitively it could detect target sequences. That matters for test design, especially when only small amounts of genetic material are present. It shows another side of CRISPR technology beyond editing DNA.","keyFindings":["Cas12 detection became more sensitive.","Signal output improved for diagnostic use.","The paper strengthened CRISPR’s role in testing technology."],"link":"https://pubs.acs.org/doi/10.1021/cbe.3c00112","researchQuestion":"The researchers wanted to understand improved Cas12-based detection methods, focusing on sensitivity and clearer signal output for practical diagnostic use?","methods":"This study improved Cas12-based detection methods, focusing on sensitivity and clearer signal output for practical diagnostic use.","mainFinding":"Cas12 detection became more sensitive. Signal output improved for diagnostic use.","whyMatters":"Sensitive nucleic-acid detection can make CRISPR useful as a diagnostic technology. This record should be source-verified before the site makes more specific performance claims.","limitations":"The linked source and the title/metadata currently stored in this project have not been independently reconciled. The diagnostic limits therefore need to be checked against the original article before adding more specific claims.","doi":"10.1021/cbe.3c00112","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Multiplex CRISPR editing in T cells for next-generation cell therapy","authors":"Roth et al.","year":2022,"journal":"Nature","technique":"CRISPR-Cas9","application":"Cell therapy","abstract":"The study examined how multiple edits could be made in T cells to build stronger cell therapy strategies for disease treatment.","summary":"T cells are important in modern medicine, especially in cancer therapy. This paper looked at making more than one edit in the same cell. That matters because complex therapies may need several changes at once. The work helps show how CRISPR can support next-generation immune treatments.","keyFindings":["More than one edit could be introduced into T cells.","The approach supported more advanced cell therapy design.","The study linked genome editing with immune-based treatment."],"link":"https://link.springer.com/article/10.1186/s12943-022-01559-z","researchQuestion":"The researchers wanted to understand examined how multiple edits could be made in T cells to build stronger cell therapy strategies for disease treatment?","methods":"The study examined how multiple edits could be made in T cells to build stronger cell therapy strategies for disease treatment.","mainFinding":"More than one edit could be introduced into T cells. The approach supported more advanced cell therapy design.","whyMatters":"Cell therapies may need several genetic changes at once. Multiplex editing can help researchers build more complex T-cell designs, but each additional edit also makes safety and quality control more important.","limitations":"Making several edits in the same T cell can increase experimental complexity. The stored source information does not provide enough detail to summarise all effects on cell fitness, off-target changes or clinical translation.","doi":"10.1186/s12943-022-01559-z","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Delivery Approaches for Therapeutic Genome Editing and Challenges","authors":"Lino et al.","year":2020,"journal":"Nature Reviews Drug Discovery","technique":"CRISPR-Cas9","application":"Review","abstract":"This review discussed the main delivery problems in therapeutic genome editing, including vector choice, tissue targeting, dose, and safety.","summary":"This is one of the most useful review topics in the field because delivery affects almost every therapy idea. The paper explains why getting the editor to the right cells is so hard. It also compares different delivery methods and their trade-offs. It is a strong overview for anyone learning the field.","keyFindings":["Delivery was presented as a core barrier to therapy.","The review compared viral and non-viral strategies.","It helped explain why successful editing needs more than a good editor."],"link":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7597956/","researchQuestion":"What does the current research show about review using CRISPR-Cas9, and what are the main opportunities and challenges?","methods":"This review discussed the main delivery problems in therapeutic genome editing, including vector choice, tissue targeting, dose, and safety.","mainFinding":"Delivery was presented as a core barrier to therapy. The review compared viral and non-viral strategies.","whyMatters":"Even an excellent genome editor cannot work as a treatment if it cannot reach the right cells. Comparing delivery approaches helps explain why vectors, tissue targeting, dose and safety are central parts of therapeutic design.","limitations":"This is a review, so it compares existing delivery approaches rather than testing one universal solution. Different tissues and editors have different delivery constraints, and the best method depends on the application.","doi":"DOI not available","researchType":"Review","citationStatus":"Metadata from current project — verify against original paper"},{"title":"CRISPR–Cas13: Pioneering RNA Editing for Nucleic Acid Therapeutics","authors":"Cox et al.","year":2024,"journal":"Cell","technique":"Cas13","application":"RNA editing","abstract":"This paper explored Cas13-based systems for editing or controlling RNA, aiming to broaden temporary and reversible gene-control methods.","summary":"RNA editing can be useful when scientists want a temporary change instead of a permanent DNA edit. This paper looked at how Cas13 could be used for that purpose. It shows that CRISPR can work at different biological levels, not just inside the genome itself.","keyFindings":["Cas13 tools expanded the possibilities for RNA-level control.","The system supported more temporary and reversible approaches.","The work broadened the overall CRISPR toolbox."],"link":"https://www.sciencedirect.com/science/article/pii/S2693125724000335","researchQuestion":"The researchers wanted to understand explored Cas13-based systems for editing or controlling RNA, aiming to broaden temporary and reversible gene-control methods?","methods":"This paper explored Cas13-based systems for editing or controlling RNA, aiming to broaden temporary and reversible gene-control methods.","mainFinding":"Cas13 tools expanded the possibilities for RNA-level control. The system supported more temporary and reversible approaches.","whyMatters":"Cas13 works at the RNA level, so its effects can be temporary rather than permanent. That widens the CRISPR toolbox for studying and potentially controlling gene output without rewriting genomic DNA.","limitations":"The stored source information describes the promise of Cas13 for RNA-level control but does not provide enough detail to establish how durable, tissue-specific or clinically effective the approaches are.","doi":"DOI not available","researchType":"Experimental study","citationStatus":"Metadata from current project — verify against original paper"},{"title":"Genome-wide CRISPR screening identifies cellular factors controlling nonviral genome editing efficiency","authors":"Saxena et al.","year":2026,"date":"13 August 2026","journal":"Nature Communications","technique":"CRISPR screening","application":"Gene delivery","abstract":"Researchers used a genome-wide CRISPR screen to identify cellular factors that influence how efficiently nonviral genome-editing systems enter cells and produce edits.","summary":"The study connected cellular delivery pathways with editing efficiency. It identified factors whose disruption improved editing outcomes, including in disease-relevant human cell models. The work suggests that improving the cell environment itself might complement improvements to delivery systems.","keyFindings":["The screen examined 19,114 human genes.","Six negative regulators of delivery were identified.","Targeting two factors improved base-editing outcomes in disease-relevant models."],"link":"https://www.nature.com/articles/s41467-026-76350-5","researchQuestion":"Which cellular factors limit the efficiency of nonviral genome editing?","methods":"The researchers performed a genome-wide CRISPR knockout screen and measured how genetic perturbations changed editing outcomes across different delivery systems and cell models.","mainFinding":"The study identified cellular regulators whose disruption increased editing efficiency, including factors linked to intracellular delivery.","whyMatters":"Genome editing often fails because editors do not reach enough target cells. Understanding cellular barriers gives researchers another route for improving therapeutic editing.","limitations":"The work was performed in specific human cell models and delivery systems. Effects in patients would require additional validation and safety testing.","doi":"10.1038/s41467-026-76350-5","researchType":"Research article","citationStatus":"Source checked"},{"title":"Mechanistic machine learning for prediction of prime editing outcomes","authors":"Hsu et al.","year":2026,"date":"12 August 2026","journal":"Nature Biotechnology","technique":"Prime editing","application":"AI-assisted editing","abstract":"Researchers developed OptiPrime, a machine-learning model built around the biological mechanisms of prime editing to predict editing efficiency and improve guide design.","summary":"Prime editing depends heavily on guide design. OptiPrime uses information about the editing mechanism rather than treating the process as a black box. The model showed strong prediction performance and was tested in therapeutic contexts, including a mouse model.","keyFindings":["OptiPrime predicts prime-editing efficiency.","The model incorporates biological mechanisms of prime editing.","The researchers tested the approach in primary cells and a mouse disease model."],"link":"https://www.nature.com/articles/s41587-026-03261-7","researchQuestion":"Can a mechanism-based machine-learning model improve prediction and design for prime editing?","methods":"The researchers trained and benchmarked OptiPrime using large datasets of prime-editing outcomes across multiple experimental conditions.","mainFinding":"OptiPrime achieved strong prediction accuracy and helped identify guide designs associated with improved editing outcomes.","whyMatters":"Better prediction could reduce trial-and-error when designing prime-editing guides and help researchers move toward more reliable therapeutic editing.","limitations":"Prediction accuracy depends on the quality and diversity of training data. Experimental validation is still required for individual editing targets.","doi":"10.1038/s41587-026-03261-7","researchType":"Research article","citationStatus":"Source checked"},{"title":"Ultra-sensitive profiling of CRISPR-Cas off-target effects with Tracking-seq2","authors":"Cong et al.","year":2026,"date":"11 August 2026","journal":"Nature Communications","technique":"Off-target analysis","application":"Safety assessment","abstract":"Tracking-seq2 is a more sensitive method for detecting unintended editing at genomic sites outside the intended target.","summary":"The researchers improved an existing off-target detection method and tested it with several genome editors. The approach worked in primary human cell types and showed that genetic differences between individuals can affect off-target patterns.","keyFindings":["Tracking-seq2 detects rare off-target events.","The method was tested with Cas9, Cas12a, base editors and prime editors.","Different individuals showed different off-target patterns."],"link":"https://www.nature.com/articles/s41467-026-76778-9","researchQuestion":"How can researchers detect rare off-target editing events with greater sensitivity in clinically relevant cells?","methods":"The team enhanced Tracking-seq with additional biochemical and repair-pathway steps, then tested it across several genome editors and primary human cell types.","mainFinding":"Tracking-seq2 improved sensitivity for profiling off-target sites and revealed variation between individuals.","whyMatters":"Reliable off-target measurement is important for evaluating the safety of therapeutic genome editors.","limitations":"The method is an assessment tool, not a treatment. Different editors and cell types still require separate validation.","doi":"10.1038/s41467-026-76778-9","researchType":"Research article","citationStatus":"Source checked"},{"title":"Towards efficient perturbation for the noncoding genome","authors":"Zhang et al.","year":2026,"date":"11 August 2026","journal":"Nature Communications","technique":"CRISPR perturbation","application":"Functional genomics","abstract":"Researchers compared CRISPR-based methods for studying noncoding DNA and developed a deep-learning model to improve guide design for genomic deletions.","summary":"Much of the human genome does not encode proteins, yet many noncoding regions regulate gene activity. This study compared several CRISPR approaches for testing those regions and introduced DeepDC to help design paired guides.","keyFindings":["Five perturbation approaches were benchmarked.","Dual-SpCas9 performed strongly for deleting regulatory regions.","DeepDC was developed to support paired-guide design."],"link":"https://www.nature.com/articles/s41467-026-76567-4","researchQuestion":"Which CRISPR perturbation strategies work best for studying functional noncoding DNA?","methods":"The researchers benchmarked multiple CRISPR loss-of-function approaches and trained a deep-learning model for paired-guide design.","mainFinding":"Different noncoding targets benefit from different perturbation strategies, and guide design can be improved computationally.","whyMatters":"Understanding noncoding DNA is important because regulatory regions influence how genes are expressed.","limitations":"The best method depended on the type of noncoding target. Results also require validation at additional loci and cell types.","doi":"10.1038/s41467-026-76567-4","researchType":"Research article","citationStatus":"Source checked"},{"title":"UNCOVERseq enables sensitive and controlled gene editing off-target nomination across CRISPR-Cas modalities and systems","authors":"Kinney et al.","year":2026,"date":"11 August 2026","journal":"Nature Communications","technique":"Off-target analysis","application":"Gene-editing safety","abstract":"UNCOVERseq is an in-cell workflow designed to identify rare unintended editing events and compare off-target risk across CRISPR systems.","summary":"The researchers created a controlled workflow for finding rare off-target sites. They benchmarked it across guide RNAs and several editing systems, including Cas9 variants and base editors.","keyFindings":["UNCOVERseq detected rare off-target events with high sensitivity.","The workflow was benchmarked across 192 guide RNAs.","It supported relative risk assessment across different editors."],"link":"https://www.nature.com/articles/s41467-026-74623-7","researchQuestion":"Can an in-cell workflow improve the detection and comparison of rare CRISPR off-target events?","methods":"The team developed UNCOVERseq and benchmarked its performance against other off-target nomination approaches across multiple editing systems.","mainFinding":"UNCOVERseq showed high sensitivity and precision for nominating off-target sites.","whyMatters":"Better off-target nomination helps researchers assess the risks of genome-editing therapies before clinical use.","limitations":"Off-target nomination identifies candidate sites for further testing. It does not by itself prove that an identified edit causes harm.","doi":"10.1038/s41467-026-74623-7","researchType":"Research article","citationStatus":"Source checked"},{"title":"Boosting genome editing in perennial plants by CRISPR-Combo mediated morphogenic gene activation","authors":"Ramasamy et al.","year":2026,"date":"5 August 2026","journal":"Nature Communications","technique":"CRISPR-Combo","application":"Plant genome editing","abstract":"Researchers used CRISPR-Combo to activate morphogenic genes while editing plant genomes, improving regeneration in several perennial crops.","summary":"Many perennial plants are difficult to transform and regenerate. The study used simultaneous gene editing and transcriptional activation to improve recovery of edited plants in potato, citrus, strawberry and poplar.","keyFindings":["Morphogenic genes improved regeneration in several crops.","The approach reduced generation time in wild strawberry.","Edited poplar shoots were produced in less than one month in the reported protocol."],"link":"https://www.nature.com/articles/s41467-026-76367-w","researchQuestion":"Can CRISPR-based activation of morphogenic genes make genome editing more efficient in difficult-to-regenerate perennial plants?","methods":"The researchers screened morphogenic genes and used CRISPR-Combo to activate selected genes during genome-editing workflows in several plant species.","mainFinding":"Activating selected morphogenic genes improved regeneration and recovery of genome-edited plants.","whyMatters":"Improved regeneration could make genome editing more practical for important perennial crops.","limitations":"The results vary by plant species and regeneration system. More work is needed to assess long-term effects and field performance.","doi":"10.1038/s41467-026-76367-w","researchType":"Research article","citationStatus":"Source checked"},{"title":"CRISPR–Cas-based live cell imaging of genome dynamics","authors":"Zhu et al.","year":2026,"date":"8 April 2026","journal":"Nature Reviews Genetics","technique":"CRISPR imaging","application":"Genome visualization","abstract":"This review examines CRISPR-based methods for visualizing DNA and RNA in living cells and tracking genome dynamics over time.","summary":"CRISPR does more than edit DNA. Researchers can use modified Cas proteins and guide RNAs to label genomic regions without cutting them. This review explains how those tools reveal chromosome organization and gene regulation in living cells.","keyFindings":["CRISPR tools enable real-time imaging of genomic regions.","Modified Cas proteins can target DNA without cutting it.","Live imaging helps researchers study genome organization and dynamics."],"link":"https://www.nature.com/articles/s41576-026-00949-z","researchQuestion":"How are CRISPR-based imaging tools being used to study genome dynamics in living cells?","methods":"The authors reviewed CRISPR-based live-cell imaging systems and the microscopy and analysis methods used with them.","mainFinding":"CRISPR imaging provides a way to observe specific genomic regions and transcripts over time in living cells.","whyMatters":"Seeing genome activity in real time gives researchers information that fixed-cell experiments cannot provide.","limitations":"Imaging systems involve trade-offs among signal strength, resolution, labeling burden and biological perturbation.","doi":"10.1038/s41576-026-00949-z","researchType":"Review article","citationStatus":"Source checked"},{"title":"Monitoring biological effects of somatic cell genome editing","authors":"Freedman et al.","year":2026,"date":"13 January 2026","journal":"Nature Reviews Genetics","technique":"Genome-editing assessment","application":"Safety and efficacy","abstract":"This review describes tools for measuring the biological effects of genome editing, from DNA-level edits to whole-organism responses.","summary":"As genome editing enters clinical development, researchers need ways to measure both intended and unintended effects. The review covers sequencing, organoids, organs-on-chips and non-invasive imaging as complementary tools.","keyFindings":["Editing outcomes need to be measured at multiple biological scales.","Organoids and organs-on-chips help assess cell and tissue responses.","Imaging can track editor distribution and activity in vivo."],"link":"https://www.nature.com/articles/s41576-025-00916-0","researchQuestion":"What tools are needed to monitor the biological effects of somatic genome editing?","methods":"The authors reviewed complementary technologies for measuring editing outcomes, cellular responses and in vivo effects.","mainFinding":"Combining DNA-level measurements with cell, tissue and whole-organism assessments provides a stronger picture of safety and efficacy.","whyMatters":"A precise DNA edit does not automatically mean a safe biological outcome. Multiple levels of assessment are needed.","limitations":"No single test captures every possible biological effect, and many approaches remain under development.","doi":"10.1038/s41576-025-00916-0","researchType":"Review article","citationStatus":"Source checked"},{"title":"Prime editing: redefining precision genome editing","authors":"Lin","year":2026,"date":"5 May 2026","journal":"Nature Reviews Genetics","technique":"Prime editing","application":"Precision editing","abstract":"This Journal Club article reviews the development and impact of prime editing, a method designed to make precise DNA changes without conventional double-strand breaks.","summary":"Prime editing expanded the types of DNA changes researchers could make with CRISPR-derived systems. The article reflects on how the technology moved from its original 2019 report into a broader genome-engineering field.","keyFindings":["Prime editing supports many types of precise DNA changes.","It uses a programmable guide and reverse-transcriptase activity.","The technology addresses limitations of standard nuclease editing and base editing."],"link":"https://www.nature.com/articles/s41576-026-00965-z","researchQuestion":"Why has prime editing become an important approach in precision genome editing?","methods":"The author reviews the development of prime editing and its impact on genome biology and engineering.","mainFinding":"Prime editing provides a versatile framework for programmable DNA rewriting without requiring a conventional double-strand break.","whyMatters":"The approach expands the range of genetic changes researchers can target with CRISPR-derived tools.","limitations":"Prime editing efficiency varies by target and guide design, so optimization remains important.","doi":"10.1038/s41576-026-00965-z","researchType":"Journal Club / review","citationStatus":"Source checked"},{"title":"New gene-editing approaches for β-hemoglobinopathies","authors":"O’Leary","year":2026,"date":"17 April 2026","journal":"Nature Medicine","technique":"Gene editing","application":"Blood disorders","abstract":"This research highlight reviews phase 1/2 clinical trials using direct editing of HBG1 and HBG2 promoters for sickle-cell disease and β-thalassemia.","summary":"Instead of directly correcting the HBB mutation, these approaches aim to reactivate fetal hemoglobin by editing regulatory regions. Early clinical results suggest this strategy is worth continued study.","keyFindings":["Three phase 1/2 trials were highlighted.","The strategy targets HBG1 and HBG2 regulatory regions.","The approach aims to increase fetal hemoglobin production."],"link":"https://www.nature.com/articles/d41591-026-00021-7","researchQuestion":"Can direct editing of fetal-hemoglobin regulatory regions provide a broadly useful strategy for inherited blood disorders?","methods":"The article summarizes results from three phase 1/2 clinical trials involving direct editing of HBG1 and HBG2 promoters.","mainFinding":"Early clinical results support promoter editing as a promising strategy for increasing fetal hemoglobin.","whyMatters":"A strategy based on reactivating fetal hemoglobin might address both sickle-cell disease and β-thalassemia.","limitations":"The highlighted trials are early-stage studies. Longer follow-up and larger groups are needed to establish durability and safety.","doi":"10.1038/d41591-026-00021-7","researchType":"Research highlight","citationStatus":"Source checked"}];
const explorerData = [{"name": "DNA", "slug": "dna", "what": "DNA is the molecule that stores most of the genetic instructions used by living cells. Its sequence is written with four chemical bases: A, T, C and G.", "why": "CRISPR tools are often designed to find a specific DNA sequence and change it. To understand gene editing, you need to know that changing even one DNA letter can sometimes change how a gene works.", "deeper": "DNA is built from two complementary strands in a double helix. Sections of DNA can contain genes, regulatory regions and other sequences. Cells copy DNA and use parts of it as instructions for making RNA and proteins.", "paperTerms": ["DNA", "mutation", "genome"]}, {"name": "Guide RNA", "slug": "guide-rna", "what": "A guide RNA is a short RNA molecule that helps a CRISPR protein find the genetic sequence scientists want to target.", "why": "The guide acts like an address. Its sequence is designed to match the target, helping a protein such as Cas9 reach the right part of the genome.", "deeper": "In many CRISPR-Cas9 systems, the guide RNA contains a targeting sequence that pairs with matching DNA. Good guide design matters because imperfect matching can reduce editing or increase the chance of activity at similar sequences.", "paperTerms": ["guide RNA", "pegRNA", "guide design"]}, {"name": "Cas9", "slug": "cas9", "what": "Cas9 is a CRISPR-associated protein that can be guided to a chosen DNA sequence and cut it.", "why": "Cas9 is one of the best-known CRISPR tools. Scientists use it to create a targeted DNA break so the cell's own repair systems can remove, disrupt or sometimes change a sequence.", "deeper": "Cas9 works with a guide RNA and usually also needs a nearby short DNA pattern called a PAM. After Cas9 cuts DNA, the result depends on how the cell repairs that break, which is why editing outcomes are not always identical.", "paperTerms": ["Cas9", "CRISPR-Cas9", "PAM"]}, {"name": "Mutations", "slug": "mutations", "what": "A mutation is a change in a DNA sequence. It can involve one DNA letter, several letters or a much larger section of DNA.", "why": "Some diseases are caused by mutations, so gene-editing research often tries to correct, remove or work around a harmful DNA change.", "deeper": "Mutations can change a protein, alter how much of a gene is used, or sometimes have little effect at all. Different editing systems are suited to different mutation types: base editors can change certain single letters, while prime editors can make a wider range of small planned changes.", "paperTerms": ["mutation", "variant", "disease-causing"]}, {"name": "Gene Expression", "slug": "gene-expression", "what": "Gene expression is the process cells use to turn genetic information into a functional product, often RNA or protein.", "why": "CRISPR does not always have to rewrite DNA. Tools such as CRISPRa and CRISPRi can raise or lower gene activity, helping scientists study what a gene does.", "deeper": "Gene expression is controlled at several stages, including whether DNA is transcribed into RNA and how that RNA is used. Changing gene expression can alter cell behaviour without changing the underlying DNA sequence.", "paperTerms": ["gene expression", "CRISPRa", "CRISPRi"]}, {"name": "CRISPR-Cas9", "slug": "crispr-cas9", "what": "CRISPR-Cas9 is a gene-editing system that uses a guide RNA to direct the Cas9 protein to a chosen DNA sequence.", "why": "It is the system that made targeted genome editing much easier to programme and is used across research, biotechnology and some therapies.", "deeper": "After Cas9 reaches a matching sequence beside a suitable PAM, it can cut DNA. The cell then repairs that break. Researchers can use the repair process to disrupt a gene or, in some settings, introduce a planned change.", "paperTerms": ["CRISPR-Cas9"]}, {"name": "Base Editing", "slug": "base-editing", "what": "Base editing changes certain DNA letters without making a standard double-strand DNA break.", "why": "Many genetic disorders are caused by a single-letter change, so base editing could be useful when the needed correction matches the chemistry an editor can perform.", "deeper": "A base editor usually combines a CRISPR targeting component with a deaminase enzyme. Different base editors can make specific chemical conversions, but they cannot correct every possible mutation and can sometimes edit nearby bases.", "paperTerms": ["Base editing"]}, {"name": "Prime Editing", "slug": "prime-editing", "what": "Prime editing is a precision gene-editing method that can write a planned small DNA change at a chosen site.", "why": "It can make several kinds of edits, including substitutions and small insertions or deletions, without relying on a standard double-strand break.", "deeper": "Prime editing combines a Cas protein that nicks DNA with a reverse transcriptase and a prime-editing guide RNA, or pegRNA. The pegRNA both guides the system and carries the template for the intended change.", "paperTerms": ["Prime editing", "pegRNA"]}, {"name": "CRISPRi", "slug": "crispri", "what": "CRISPR interference, or CRISPRi, reduces the activity of a target gene without cutting its DNA sequence.", "why": "It lets researchers ask what happens when a gene is turned down, which is useful for studying pathways and finding genes involved in disease.", "deeper": "CRISPRi usually uses a catalytically inactive Cas protein that can still be guided to DNA. Instead of cutting, it blocks transcription directly or carries proteins that repress gene activity.", "paperTerms": ["CRISPRi"]}, {"name": "CRISPRa", "slug": "crispra", "what": "CRISPR activation, or CRISPRa, increases the activity of a target gene without cutting its DNA.", "why": "It helps researchers test what happens when a gene is switched on more strongly and can reveal genes that change cell state or behaviour.", "deeper": "CRISPRa uses a DNA-targeting Cas protein that has been disabled as a nuclease and attached to activation machinery. The guide RNA brings that complex near a gene so the cell is encouraged to transcribe it.", "paperTerms": ["CRISPRa"]}, {"name": "Cas12", "slug": "cas12", "what": "Cas12 is a family of CRISPR proteins that can be guided to DNA targets and has properties that differ from Cas9.", "why": "Different PAM requirements and cutting behaviour can make Cas12 useful at targets that are less convenient for other CRISPR systems.", "deeper": "Cas12 proteins use guide RNA to recognise matching DNA. Some Cas12 enzymes also show collateral activity after target recognition, a property that researchers have adapted for nucleic-acid detection.", "paperTerms": ["Cas12", "Cas12a"]}, {"name": "Cas13", "slug": "cas13", "what": "Cas13 is a family of CRISPR proteins that targets RNA rather than DNA.", "why": "Because it works at the RNA level, Cas13 can change gene output without permanently rewriting the genome and can also be used in detection systems.", "deeper": "A guide RNA directs Cas13 to a matching RNA sequence. Depending on the system, researchers can use this to reduce an RNA target, study RNA biology or trigger a detectable signal for diagnostics.", "paperTerms": ["Cas13", "Cas13d"]}];
let current=null;
let currentTech=0;
let timer=null;

function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function linkConcepts(text){
  let out=escapeHtml(text);
  const terms=[['gene expression','gene-expression'],['guide RNA','guide-rna'],['mutations','mutations'],['mutation','mutations'],['Cas9','cas9'],['DNA','dna']];
  terms.forEach(([term,slug])=>{out=out.replace(new RegExp(`\\b${term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}\\b`,'gi'),m=>`<button class="concept-link" onclick="openConcept('${slug}')">${m}</button>`);});
  return out;
}
function buildHelix(){
  const host=document.getElementById('helix'); if(!host)return;
  for(let i=0;i<17;i++){const pair=document.createElement('div');pair.className='pair';pair.style.top=(6+i*19.5)+'px';const offset=Math.sin(i*.72)*58;const width=104+Math.abs(offset)*1.15;const left=document.createElement('div');left.className='node';left.style.left=`calc(50% - ${offset+8}px)`;const right=document.createElement('div');right.className='node';right.style.left=`calc(50% + ${offset-8}px)`;const line=document.createElement('div');line.className='line';line.style.width=width+'px';line.style.left=`calc(50% - ${width/2}px)`;pair.appendChild(line);pair.appendChild(left);pair.appendChild(right);host.appendChild(pair);}
}
function filtered(){const q=document.getElementById('search').value.toLowerCase().trim(),y=document.getElementById('year').value,t=document.getElementById('technique').value,s=document.getElementById('sort').value;let a=papers.filter(p=>{const hay=`${p.title} ${p.authors} ${p.journal} ${p.technique} ${p.application} ${p.abstract}`.toLowerCase();return(!q||hay.includes(q))&&(!y||String(p.year)===y)&&(!t||p.technique===t);});if(s==='newest')a.sort((a,b)=>b.year-a.year);if(s==='oldest')a.sort((a,b)=>a.year-b.year);if(s==='alpha')a.sort((a,b)=>a.title.localeCompare(b.title));return a;}
function renderPapers(){const a=filtered();document.getElementById('paperCount').textContent=`${a.length} of ${papers.length} papers`;if(!a.length){document.getElementById('paperList').innerHTML='<div class="paper"><div class="paper-title">No papers match those filters.</div></div>';document.getElementById('detail').innerHTML='';current=null;return;}if(!current||!a.some(p=>p.title===current.title))current=a[0];document.getElementById('paperList').innerHTML=a.map((p,i)=>`<article class="paper ${current.title===p.title?'active':''}" onclick='openPaper(${JSON.stringify(p.title)})'><div class="paper-index">${String(i+1).padStart(2,'0')}</div><div class="paper-title">${escapeHtml(p.title)}</div><div class="paper-meta">${escapeHtml(p.authors)} · ${escapeHtml(p.journal)} · ${p.year}${p.date ? ` · ${escapeHtml(p.date)}` : ""}</div></article>`).join('');renderDetail();}
function openPaper(title){current=papers.find(p=>p.title===title);if(timer)clearTimeout(timer);renderPapers();if(innerWidth<1000)document.getElementById('detail').scrollIntoView({behavior:'smooth',block:'start'});}
function researchSection(num,title,text){return `<section class="research-guide-block"><div class="guide-number">${num}</div><div><h4>${title}</h4><p>${linkConcepts(text)}</p></div></section>`;}
function renderDetail(){const p=current;if(!p)return;document.getElementById('detail').innerHTML=`<div class="detail-tag">${escapeHtml(p.technique)} · ${escapeHtml(p.application)}</div><h3>${escapeHtml(p.title)}</h3><div class="detail-meta">${escapeHtml(p.authors)} · ${escapeHtml(p.journal)} · ${p.year}${p.date ? ` · ${escapeHtml(p.date)}` : ""}</div><div class="paper-actions"><button class="paper-button active-tab" onclick="showGuide(this)">Research guide</button><button class="paper-button ai-btn" onclick="runAI(this)">AI Tutor</button><a class="paper-button source-btn" href="${p.link}" target="_blank" rel="noopener noreferrer">Original paper ↗</a></div><div id="paperContent"></div><div id="aiMount"></div>`;showGuide();}
function showGuide(btn){document.querySelectorAll('.paper-actions .paper-button').forEach(x=>x.classList.remove('active-tab'));if(btn)btn.classList.add('active-tab');document.getElementById('aiMount').innerHTML='';const p=current;document.getElementById('paperContent').innerHTML=`<div class="guide-intro"><span>Student research guide</span><p>Start with the question, then work through what the researchers did and what the evidence can actually support.</p></div>${researchSection('01','Research Question',p.researchQuestion)}${researchSection('02','What the Researchers Did',p.methods)}${researchSection('03','Main Finding',p.mainFinding)}${researchSection('04','Why It Matters',p.whyMatters)}${researchSection('05','Limitations',p.limitations)}<section class="sources-panel"><div class="guide-number">07</div><div class="sources-content"><h4>Original Research / Sources</h4><dl><div><dt>Authors</dt><dd>${escapeHtml(p.authors)}</dd></div><div><dt>Journal</dt><dd>${escapeHtml(p.journal)}</dd></div><div><dt>Year</dt><dd>${p.year}</dd></div><div><dt>DOI</dt><dd>${escapeHtml(p.doi)}</dd></div><div><dt>Research Type</dt><dd>${escapeHtml(p.researchType)}</dd></div></dl><a class="source-link" href="${p.link}" target="_blank" rel="noopener noreferrer">Open the original source ↗</a><p class="source-status ${p.citationStatus==='Source checked'?'checked':''}">${escapeHtml(p.citationStatus)}</p></div></section>`;}
const tutorPrompts=[
  'Explain this like I’m new to biology.',
  'What is the most important finding?',
  'What are the limitations of this study?',
  'What background knowledge do I need?',
  'How does this connect to CRISPR?'
];
let tutorHistory=[];
let tutorPaperTitle='';

function tutorPaperContext(p){
  return {
    title:p.title,
    authors:p.authors,
    year:p.year,
    journal:p.journal,
    technique:p.technique,
    application:p.application,
    abstract:p.abstract,
    researchQuestion:p.researchQuestion,
    methods:p.methods,
    mainFinding:p.mainFinding,
    whyMatters:p.whyMatters,
    limitations:p.limitations,
    doi:p.doi,
    researchType:p.researchType,
    sourceUrl:p.link,
    citationStatus:p.citationStatus
  };
}

function runAI(btn){
  document.querySelectorAll('.paper-actions .paper-button').forEach(x=>x.classList.remove('active-tab'));
  if(btn)btn.classList.add('active-tab');
  document.getElementById('paperContent').innerHTML='';
  const mount=document.getElementById('aiMount');
  if(tutorPaperTitle!==current.title){tutorHistory=[];tutorPaperTitle=current.title;}
  mount.innerHTML=`<div class="ai-output tutor">
    <div class="ai-header"><div><strong>AI Tutor</strong><span>Ask anything about this paper or the science behind it</span></div><span class="live-ai-label">live AI</span></div>
    <p class="tutor-note">Ask your own question or start with one of these. For paper-specific claims, the tutor uses the research guide and source details on this page as context and will tell you when the available information is not enough.</p>
    <div class="prompt-grid">${tutorPrompts.map(q=>`<button type="button" onclick='submitTutorPrompt(${JSON.stringify(q)})'>${escapeHtml(q)}</button>`).join('')}</div>
    <div id="tutorConversation" class="tutor-conversation" aria-live="polite"></div>
    <form class="tutor-form" onsubmit="askTutor(event)">
      <textarea id="tutorQuestion" rows="2" placeholder="Ask any question… e.g. Why did they use lipid nanoparticles?" aria-label="Ask the AI Tutor a question"></textarea>
      <button id="tutorAskButton" type="submit">Ask</button>
    </form>
    <div id="tutorStatus" class="tutor-status"></div>
  </div>`;
  renderTutorHistory();
}

function renderTutorHistory(){
  const box=document.getElementById('tutorConversation');
  if(!box)return;
  if(!tutorHistory.length){box.innerHTML='<div class="tutor-empty">Your conversation will appear here.</div>';return;}
  box.innerHTML=tutorHistory.map(m=>`<div class="chat-row ${m.role}"><div class="chat-label">${m.role==='user'?'You':'AI Tutor'}</div><div class="chat-bubble">${escapeHtml(m.content).replace(/\n/g,'<br>')}</div></div>`).join('');
  box.scrollTop=box.scrollHeight;
}

function submitTutorPrompt(q){
  const input=document.getElementById('tutorQuestion');
  if(input)input.value=q;
  askTutor(new Event('submit'));
}

async function askTutor(e){
  if(e&&e.preventDefault)e.preventDefault();
  const input=document.getElementById('tutorQuestion');
  const button=document.getElementById('tutorAskButton');
  const status=document.getElementById('tutorStatus');
  if(!input||!current)return;
  const question=input.value.trim();
  if(!question)return;

  const priorHistory=tutorHistory.slice(-10);
  tutorHistory.push({role:'user',content:question});
  input.value='';
  renderTutorHistory();
  button.disabled=true;
  button.textContent='Thinking…';
  status.textContent='The AI Tutor is working on your question.';

  try{
    const response=await fetch('/api/tutor',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({question,paper:tutorPaperContext(current),history:priorHistory})
    });
    const data=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(data.error||'The AI Tutor could not answer right now.');
    tutorHistory.push({role:'assistant',content:data.answer||'I could not generate an answer.'});
    status.textContent='';
  }catch(err){
    tutorHistory.push({role:'assistant',content:`I couldn’t connect to the AI service. ${err.message} If you are opening this as a local HTML file, deploy the full project with the secure API endpoint first.`});
    status.textContent='Connection error';
  }finally{
    button.disabled=false;
    button.textContent='Ask';
    renderTutorHistory();
    input.focus();
  }
}
function renderTech(){document.getElementById('techNav').innerHTML=explorerData.map((x,i)=>`<button class="tech-btn ${i===currentTech?'active':''}" onclick="openTech(${i})"><strong>${x.name}</strong><span>${String(i+1).padStart(2,'0')}</span></button>`).join('');openTech(currentTech,false);}
function openTech(i,scroll=false){currentTech=i;document.querySelectorAll('.tech-btn').forEach((b,j)=>b.classList.toggle('active',i===j));const x=explorerData[i];document.getElementById('techContent').innerHTML=`<div class="concept-kicker">Foundational concept</div><h3 id="concept-${x.slug}">${x.name}</h3><div class="tech-definition">${x.what}</div><div class="factlist"><div class="factrow"><strong>Why does it matter for CRISPR?</strong><p>${x.why}</p></div><div class="factrow"><strong>A slightly deeper explanation</strong><p>${x.deeper}</p></div><div class="factrow related-row"><strong>Find it in the research</strong><p>${relatedPapers(x).map(p=>`<button onclick='jumpToPaper(${JSON.stringify(p.title)})'>${escapeHtml(p.title)}</button>`).join('')||'No direct paper match is tagged in the current collection.'}</p></div></div>`;if(scroll)document.getElementById('explorer').scrollIntoView({behavior:'smooth',block:'start'});}
function relatedPapers(x){return papers.filter(p=>x.paperTerms.some(t=>`${p.title} ${p.abstract} ${p.technique}`.toLowerCase().includes(t.toLowerCase()))).slice(0,3);}
function openConcept(slug){const i=explorerData.findIndex(x=>x.slug===slug);if(i>=0)openTech(i,true);}
function jumpToPaper(title){document.getElementById('search').value='';document.getElementById('year').value='';document.getElementById('technique').value='';current=papers.find(p=>p.title===title);renderPapers();document.getElementById('research').scrollIntoView({behavior:'smooth',block:'start'});}
['search','year','technique','sort'].forEach(id=>{document.getElementById(id).addEventListener('input',renderPapers);document.getElementById(id).addEventListener('change',renderPapers);});
buildHelix();renderPapers();renderTech();
